import { App } from "@modelcontextprotocol/ext-apps";

// Crypto utilities using Web Crypto API
async function deriveKey(passphrase: string, salt: Uint8Array): Promise<CryptoKey> {
  const encoder = new TextEncoder();
  const keyMaterial = await crypto.subtle.importKey(
    "raw",
    encoder.encode(passphrase),
    "PBKDF2",
    false,
    ["deriveKey"]
  );

  return crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt: salt.buffer as ArrayBuffer,
      iterations: 100000,
      hash: "SHA-256",
    },
    keyMaterial,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"]
  );
}

async function encrypt(text: string, passphrase: string): Promise<{ data: string; iv: string }> {
  const encoder = new TextEncoder();
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const key = await deriveKey(passphrase, salt);

  const encrypted = await crypto.subtle.encrypt(
    { name: "AES-GCM", iv: iv.buffer as ArrayBuffer },
    key,
    encoder.encode(text)
  );

  // Combine salt + encrypted data
  const combined = new Uint8Array(salt.length + encrypted.byteLength);
  combined.set(salt);
  combined.set(new Uint8Array(encrypted), salt.length);

  return {
    data: btoa(String.fromCharCode(...combined)),
    iv: btoa(String.fromCharCode(...iv)),
  };
}

async function decrypt(encryptedData: string, iv: string, passphrase: string): Promise<string> {
  const combined = Uint8Array.from(atob(encryptedData), (c) => c.charCodeAt(0));
  const ivBytes = Uint8Array.from(atob(iv), (c) => c.charCodeAt(0));

  // Extract salt (first 16 bytes) and encrypted content
  const salt = combined.slice(0, 16);
  const data = combined.slice(16);

  const key = await deriveKey(passphrase, salt);

  const decrypted = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv: ivBytes.buffer as ArrayBuffer },
    key,
    data
  );

  return new TextDecoder().decode(decrypted);
}

// DOM Elements
const tabs = document.querySelectorAll<HTMLButtonElement>(".tab");
const createPanel = document.getElementById("create-panel")!;
const revealPanel = document.getElementById("reveal-panel")!;

const secretText = document.getElementById("secret-text") as HTMLTextAreaElement;
const passphrase = document.getElementById("passphrase") as HTMLInputElement;
const ttlInput = document.getElementById("ttl") as HTMLInputElement;
const maxViewsInput = document.getElementById("max-views") as HTMLInputElement;
const createBtn = document.getElementById("create-btn") as HTMLButtonElement;
const createResult = document.getElementById("create-result")!;

const secretIdInput = document.getElementById("secret-id") as HTMLInputElement;
const revealPassphrase = document.getElementById("reveal-passphrase") as HTMLInputElement;
const revealBtn = document.getElementById("reveal-btn") as HTMLButtonElement;
const revealResult = document.getElementById("reveal-result")!;

// Tab switching
tabs.forEach((tab) => {
  tab.addEventListener("click", () => {
    tabs.forEach((t) => t.classList.remove("active"));
    tab.classList.add("active");

    const tabName = tab.dataset.tab;
    createPanel.classList.toggle("active", tabName === "create");
    revealPanel.classList.toggle("active", tabName === "reveal");
  });
});

// MCP App instance
const app = new App({ name: "OneTime Secret", version: "1.0.0" });

// Handle tool results from initial load
app.ontoolresult = (result) => {
  const text = result.content?.find((c) => c.type === "text")?.text;
  if (text) {
    try {
      const data = JSON.parse(text);
      if (data.secretId) {
        showCreateResult(data);
      }
    } catch {
      // Ignore parse errors
    }
  }
};

// Create secret
createBtn.addEventListener("click", async () => {
  const text = secretText.value.trim();
  const pass = passphrase.value;

  if (!text) {
    showError(createResult, "Please enter a secret message");
    return;
  }
  if (!pass) {
    showError(createResult, "Please enter a passphrase");
    return;
  }

  createBtn.disabled = true;
  createBtn.textContent = "Encrypting...";

  try {
    const { data, iv } = await encrypt(text, pass);

    const result = await app.callServerTool({
      name: "create-secret",
      arguments: {
        encryptedData: data,
        iv,
        ttlMinutes: parseInt(ttlInput.value) || 60,
        maxViews: parseInt(maxViewsInput.value) || 1,
      },
    });

    const response = JSON.parse(
      result.content?.find((c) => c.type === "text")?.text || "{}"
    );

    if (response.success) {
      showCreateResult(response);
      // Clear form
      secretText.value = "";
      passphrase.value = "";
    } else {
      showError(createResult, response.error || "Failed to create secret");
    }
  } catch (err) {
    showError(createResult, `Error: ${err instanceof Error ? err.message : "Unknown error"}`);
  } finally {
    createBtn.disabled = false;
    createBtn.textContent = "🔒 Create Secret";
  }
});

// Reveal secret
revealBtn.addEventListener("click", async () => {
  const secretId = secretIdInput.value.trim();
  const pass = revealPassphrase.value;

  if (!secretId) {
    showError(revealResult, "Please enter a secret ID");
    return;
  }
  if (!pass) {
    showError(revealResult, "Please enter the passphrase");
    return;
  }

  revealBtn.disabled = true;
  revealBtn.textContent = "Retrieving...";

  try {
    const result = await app.callServerTool({
      name: "reveal-secret",
      arguments: { secretId },
    });

    const response = JSON.parse(
      result.content?.find((c) => c.type === "text")?.text || "{}"
    );

    if (response.success) {
      const decrypted = await decrypt(response.encryptedData, response.iv, pass);
      showRevealResult(decrypted, response.destroyed, response.viewsRemaining);
      // Clear form
      secretIdInput.value = "";
      revealPassphrase.value = "";
    } else {
      showError(revealResult, response.error || "Secret not found or expired");
    }
  } catch (err) {
    if (err instanceof Error && err.message.includes("decrypt")) {
      showError(revealResult, "Decryption failed - wrong passphrase?");
    } else {
      showError(revealResult, `Error: ${err instanceof Error ? err.message : "Unknown error"}`);
    }
  } finally {
    revealBtn.disabled = false;
    revealBtn.textContent = "🔓 Reveal Secret";
  }
});

function showCreateResult(data: { secretId: string; expiresAt: string; maxViews: number }) {
  const workerUrl = (window as any).WORKER_URL || "http://localhost:8787";
  const shareUrl = `${workerUrl}/s/${data.secretId}`;
  const passphraseValue = passphrase.value;
  const shareUrlWithKey = `${shareUrl}#${encodeURIComponent(passphraseValue)}`;

  createResult.className = "result success";
  createResult.style.display = "block";
  createResult.innerHTML = `
    <strong>✅ Secret Created!</strong>

    <div style="margin-top: 12px;">
      <label style="font-size: 12px; color: #666; display: block; margin-bottom: 4px;">Secret ID:</label>
      <div class="secret-link">${data.secretId}</div>
      <button class="copy-btn" onclick="navigator.clipboard.writeText('${data.secretId}').then(() => this.textContent = '✓ Copied!')">📋 Copy ID</button>
    </div>

    <div style="margin-top: 16px;">
      <label style="font-size: 12px; color: #666; display: block; margin-bottom: 4px;">Shareable Link (ID only - passphrase separate):</label>
      <div class="secret-link" style="font-size: 11px;">${escapeHtml(shareUrl)}</div>
      <button class="copy-btn" onclick="navigator.clipboard.writeText('${shareUrl}').then(() => this.textContent = '✓ Copied!')">📋 Copy Link</button>
    </div>

    <div style="margin-top: 16px;">
      <label style="font-size: 12px; color: #666; display: block; margin-bottom: 4px;">One-Click Link (includes passphrase in URL fragment):</label>
      <div class="secret-link" style="font-size: 11px;">${escapeHtml(shareUrlWithKey)}</div>
      <button class="copy-btn" onclick="navigator.clipboard.writeText('${shareUrlWithKey}').then(() => this.textContent = '✓ Copied!')">📋 Copy One-Click Link</button>
      <p class="warning" style="font-size: 11px; margin-top: 4px;">⚠️ Less secure: passphrase is in the URL</p>
    </div>

    <p style="margin-top: 12px; font-size: 13px;">Expires: ${new Date(data.expiresAt).toLocaleString()}</p>
    <p style="font-size: 13px;">Max views: ${data.maxViews}</p>
  `;
}

function showRevealResult(secret: string, destroyed: boolean, viewsRemaining: number) {
  revealResult.className = "result success";
  revealResult.style.display = "block";
  revealResult.innerHTML = `
    <strong>🔓 Secret Revealed</strong>
    <div class="revealed-secret">${escapeHtml(secret)}</div>
    <button class="copy-btn" onclick="navigator.clipboard.writeText(${JSON.stringify(secret)})">📋 Copy Secret</button>
    ${destroyed 
      ? '<p class="warning">🔥 This secret has been destroyed!</p>' 
      : `<p>Views remaining: ${viewsRemaining}</p>`
    }
  `;
}

function showError(element: HTMLElement, message: string) {
  element.className = "result error";
  element.style.display = "block";
  element.innerHTML = `<strong>❌ Error:</strong> ${escapeHtml(message)}`;
}

function escapeHtml(text: string): string {
  const div = document.createElement("div");
  div.textContent = text;
  return div.innerHTML;
}

// Connect to host
app.connect();

